        setOnlineStatus() {
            var parent = this;
            var name = parent.get_name();

            if (name) {
                var usersRef = firebase.database().ref('users').child(name);

                // Mettre le statut en ligne lorsqu'il est sur la page
                usersRef.update({ status: 'online' });

                // Définir le statut inactif lorsqu'il quitte la page
                window.addEventListener('beforeunload', function () {
                    usersRef.update({ status: 'offline' });
                });

                // Définir le statut en ligne lorsqu'il revient à la page
                window.addEventListener('focus', function () {
                    usersRef.update({ status: 'online' });
                });
            }
            setInterval(function () {
                // Requête à la base de données Firebase pour obtenir les dernières informations sur les utilisateurs
                usersRef.once('value').then(function (snapshot) {
                    parent.updateTypingIndicators(snapshot.val());
                });
            }, 1000); // Exécute la fonction toutes les 1 seconde (ajustez la fréquence selon vos besoins)

        }


        setupTypingIndicator() {
            var parent = this;
            var chat_input = document.getElementById('chat_input');
            var typingRef = firebase.database().ref('users/' + parent.get_name() + '/typing');

            var usersRef = firebase.database().ref('users');
            var typingTimer; // Variable pour stocker le timer
            var typingPopups = {}; // Stocke les références des popups créées

            chat_input.addEventListener('input', function () {
                typingRef.set(servp); // Met à jour la variable 'typing' dans la base de données à true
                clearTimeout(typingTimer);

                // Définir un délai pour s'assurer que l'utilisateur n'a pas simplement perdu temporairement le focus
                typingTimer = setTimeout(function () {
                    typingRef.set('false'); // Met à jour la variable 'typing' dans la base de données à false
                }, 1000); // Attendre 0.5 seconde avant de déclencher 'blur'
            });

            // Vérifier périodiquement l'état de la saisie
            setInterval(function () {
                usersRef.once('value').then(function (snapshot) {
                    parent.updateTypingIndicators(snapshot.val(), typingPopups);
                });
            }, 1000);

        }

        updateTypingIndicators(users, typingPopups) {
            // Parcourir les utilisateurs pour détecter ceux qui écrivent
            for (var userId in users) {
                if (users.hasOwnProperty(userId)) {
                    var user = users[userId];

                    if (user.typing === servp && user.typing) {
                        // Vérifier si une popup existe déjà pour cet utilisateur
                        if (!typingPopups[userId]) {
                            // Créer une nouvelle instance de popup et la stocker dans l'objet typingPopups
                            var popup = document.createElement('div');
                            popup.className = 'typing-popup';
                            popup.textContent = userId + ' est en train d\'écrire';
                            chat_inner_container.appendChild(popup);
                            typingPopups[userId] = popup;
                        }
                    } else {
                        // Si l'utilisateur n'est pas en train d'écrire, supprimer la popup s'il y en a une
                        if (typingPopups[userId]) {
                            typingPopups[userId].remove();
                            delete typingPopups[userId];
                        }
                    }
                }
            }
        }


