                searchIcon.appendChild(searchPath);

                var searchInput = document.createElement('input');
                searchInput.setAttribute('placeholder', 'Search');
                searchInput.setAttribute('type', 'search');
                searchInput.setAttribute('class', 'input');

                searchDiv.appendChild(searchIcon);
                searchDiv.appendChild(searchInput);
                // Add a close button to the people list
                var closeButton = document.createElement('button');
                closeButton.textContent = '✖';
                closeButton.onclick = function () {
                    peopleListContainer.remove();
                };

                var peopleList = document.createElement('ul');
                snapshot.forEach(function (childSnapshot) {
                    var childData = childSnapshot.val();
                    var personName = childData.name;

                    if (personName) {
                        var personListItem = document.createElement('li');
                        personListItem.textContent = personName;

                        personListItem.addEventListener('click', function () {
                            app.initiatePrivateChat(personName);
                            app.affichageduboutonderetour()
                        });

                        peopleList.appendChild(personListItem);
                    }
                });
                // Add event listener for search input
                searchInput.addEventListener('input', function () {
                    var searchTerm = searchInput.value.toLowerCase();
                    Array.from(peopleList.children).forEach(function (item) {
                        var itemName = item.textContent.toLowerCase();
                        item.style.display = itemName.includes(searchTerm) ? 'block' : 'none';
                    });
                });


                // Append the close button and people list to the container
                peopleListContainer.appendChild(searchDiv);
                peopleListContainer.appendChild(closeButton);
                peopleListContainer.appendChild(peopleList);

                // Append the people list container to the document body
                document.body.appendChild(peopleListContainer);

                // Add an event listener to close the people list when clicking outside of it
                document.addEventListener('click', function closePeopleList(event) {
                    if (!peopleListContainer.contains(event.target)) {
                        peopleListContainer.remove();
                        document.removeEventListener('click', closePeopleList); // Remove the event listener
                    }
                });

                // Add an event listener to close the people list when changing the chat
                window.addEventListener('changeChat', function () {
                    peopleListContainer.remove();

                });
            });
        }
