            password_input.placeholder = 'Et le mot de passe là';
            password_input.required
            if (password_input === "") {
                alert("Le mot de passe est vide. Veuillez entrer un mot de passe valide.");
                return;
            }
            if (password_input === " ") {
                alert("Le mot de passe est vide. Veuillez entrer un mot de passe valide.");
                return;
            }
            join_input.onkeyup = function () {
                if (join_input.value.length > 0 || password_input.value.length > 0) {
                    join_button.classList.add('enabled')
                    join_button.onclick = function () {
                        var name = join_input.value;
                        var password = password_input.value;
                        var databaseRef = firebase.database().ref();
                        var usersRef = databaseRef.child('users');
                        var userExists = false;

                        usersRef.on('value', function (snapshot) {
                            var usersData = snapshot.val();
                            for (var userId in usersData) {
                                var user = usersData[userId];
                                if (user.name === name) {
                                    userExists = true;
                                    if (user.password === password) {
                                        parent.save_name(name);
                                        join_container.remove();
                                        alert('Connecter à ' + name)
                                        window.location.reload();
                                        parent.create_chats();
                                    } else {
                                        alert('Mauvais mot de passe. Veuillez réessayer. Si le probleme persiste damandé à ce mail <PRESIDIO_ANONYMIZED_EMAIL_ADDRESS>');
                                    }
                                    break;
                                }
                            }

                            if (!userExists) {
                                var newUserRef = usersRef.push();
                                newUserRef.set({ name: name, password: password });
                                parent.save_name(name);
                                join_container.remove();
                                alert('Utilisateur crée')
                                window.location.reload();
                                parent.create_chat();
                            }
                        });
                    }
                } else {
                    join_button.classList.remove('enabled')
                }
            }

            join_button_container.append(join_button)
            join_input_container.append(join_input, password_input)
            join_inner_container.append(join_input_container, join_button_container)
            join_container.append(join_inner_container)
            document.body.append(join_container)
        }



