```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class MessageAnalyzer
{
    // Liste de mots-clés offensants
    private static readonly HashSet<string> OffensiveWords = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        "idiot", "imbécile", "stupide", "imbécile", "crétin", "abrutit", "abruti"
    };

    // Méthode pour déterminer si un message est offensant
    public (bool IsOffensive, string Reason) IsMessageOffensive(string message)
    {
        if (string.IsNullOrWhiteSpace(message))
        {
            return (false, "Le message est vide ou ne contient que des espaces.");
        }

        // Vérifier si le message contient un mot-clé offensant
        var offensiveWord = OffensiveWords.FirstOrDefault(word => message.Contains(word, StringComparison.OrdinalIgnoreCase));

        if (offensiveWord != null)
        {
            return (true, $"Le message contient le mot-clé offensant : '{offensiveWord}'.");
        }

        // Vérifier si le message contient des majuscules excessives (crier)
        if (message.Any(char.IsUpper) && message.Count(char.IsUpper) > message.Length / 2)
        {
            return (true, "Le message contient trop de majuscules, ce qui peut être perçu comme un cri.");
        }

        // Vérifier si le message contient des caractères spéciaux excessifs
        if (message.Count(char.IsSymbol) > 5)
        {
            return (true, "Le message contient trop de caractères spéciaux, ce qui peut être perçu comme agressif.");
        }

        // Si aucune condition offensante n'est remplie
        return (false, "Le message ne contient pas de contenu offensant.");
    }
}
