        this.degats = degats;
    }

    public String getNom() {
        return nom;
    }

    public int getDegats() {
        return degats;
    }

    public void afficherDetails() {
        System.out.println("Nom: " + nom);
        System.out.println("Dégâts: " + degats);
    }
}
```

**Main.java**
```java
public class Main {
    public static void main(String[] args) {
        // Créer un tableau d'objets Arme
        Arme[] armes = new Arme[3];
        armes[0] = new Arme("Épée", 10);
        armes[1] = new Arme("Hache", 15);
        armes[2] = new Arme("Arc", 8);

        // Afficher les détails de chaque arme
        for (int i = 0; i < armes.length; i++) {
            System.out.println("Arme " + (i + 1) + ":");
            armes[i].afficherDetails();
            System.out.println();
        }

        // Boucle pour la sélection
        while (true) {
            System.out.print("Entrez le numéro de l'arme que vous souhaitez sélectionner (1-3), ou 0 pour quitter : ");
            int choix = Integer.parseInt(System.console().readLine());

            if (choix == 0) {
                break;
            } else if (choix >= 1 && choix <= 3) {
                System.out.println("Vous avez sélectionné :");
                armes[choix - 1].afficherDetails();
            } else {
                System.out.println("Choix invalide. Veuillez réessayer.");
            }
        }
    }
}
